INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S2-Q2$batch13$, 144, 2, 2, $batch13$Most Strongly Supported$batch13$, $batch13$Government official: Residents who are foreign citizens can serve as public servants at most levels, but not as cabinet secretaries. This is wise, since cabinet secretaries perform some duties that should be performed only by citizens, and no one should be appointed to a position if it involves duties that person should not perform. Moreover, a cabinet undersecretary is expected to serve as cabinet secretary when the actual secretary is unavailable. So, _______.$batch13$, $batch13$Which one of the following most logically completes the government official’s statement?$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$foreign citizens who serve as public servants should be granted citizenship in the country they serve$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$foreign citizens should not be appointed as cabinet undersecretaries$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$only former cabinet undersecretaries should be appointed as cabinet secretaries$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$foreign citizens should be eligible to serve as cabinet secretaries$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$cabinet undersecretaries should not be expected to stand in for cabinet secretaries$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Statements$batch13$, $batch13$Foreign citizens can't serve as cabinet secretaries, because secretaries perform some duties only citizens should perform. No one should hold a position involving duties they shouldn't perform. A cabinet undersecretary is expected to serve as secretary when the secretary is unavailable.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$An undersecretary may have to do a secretary's duties. Some of those duties are for citizens only. So the undersecretary role involves duties a foreign citizen shouldn't perform.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Foreign citizens shouldn't be appointed undersecretaries.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Nothing supports granting citizenship.$batch13$), ($batch13$B$batch13$, $batch13$The undersecretary job includes standing in as secretary, and foreign citizens shouldn't hold a job with those duties.$batch13$), ($batch13$C$batch13$, $batch13$Nothing limits who can become secretary to former undersecretaries.$batch13$), ($batch13$D$batch13$, $batch13$The official says this rule is wise.$batch13$), ($batch13$E$batch13$, $batch13$The official takes the stand-in expectation as given and draws a conclusion from it.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S2-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
